import{_ as r,o as t,c as n,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const g=JSON.parse('{"title":"Klassen und Unterricht vorbereiten","description":"","frontmatter":{},"headers":[],"relativePath":"schild3/unterricht-kataloge.md","filePath":"schild3/unterricht-kataloge.md"}'),s={name:"schild3/unterricht-kataloge.md"};function h(i,e,l,u,d,c){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="klassen-und-unterricht-vorbereiten" tabindex="-1">Klassen und Unterricht vorbereiten <a class="header-anchor" href="#klassen-und-unterricht-vorbereiten" aria-label="Permalink to &quot;Klassen und Unterricht vorbereiten&quot;">​</a></h1><p>Bereiten Sie die Unterrichtsstruktur vor, bevor Sie Fächer und Kurse Schülerinnen und Schülern zuweisen. Klassen und Kurse werden für den jeweils gewählten Lernabschnitt gepflegt.</p><h2 id="jahrgange-und-klassen-einrichten" tabindex="-1">Jahrgänge und Klassen einrichten <a class="header-anchor" href="#jahrgange-und-klassen-einrichten" aria-label="Permalink to &quot;Jahrgänge und Klassen einrichten&quot;">​</a></h2><ol><li><a href="/schild3/unterricht-kataloge/jahrgaenge-schulbezogene-kataloge.html">Jahrgänge und ihre Statistikzuordnung festlegen</a>.</li><li><a href="/zeugnisse/vorbereitung/klassen-versetzungstabelle-schulbezogene-kataloge.html">Klassen, Folgeklassen und Prüfungsordnungen festlegen</a> und den richtigen Lernabschnitt wählen.</li><li>Bei Bedarf <a href="/schild3/unterricht-kataloge/klassengruppen-abteilungen-schulbezogene-kataloge.html">Abteilungen und Klassengruppen</a> bilden.</li></ol><h2 id="facher-und-unterricht-vorbereiten" tabindex="-1">Fächer und Unterricht vorbereiten <a class="header-anchor" href="#facher-und-unterricht-vorbereiten" aria-label="Permalink to &quot;Fächer und Unterricht vorbereiten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Fachmerkmale, Zeugnisdruck und Teilleistungen festlegen</td><td><a href="/schild3/unterricht-kataloge/unterrichtsfaecher-schulbezogene-kataloge.html">Unterrichtsfächer</a></td></tr><tr><td>Fächersätze für Jahrgänge oder Klassen vorbereiten</td><td><a href="/schild3/unterricht-kataloge/stundentafel-schulbezogene-kataloge.html">Stundentafeln</a></td></tr><tr><td>Klassenunterricht über Stundentafeln aufbauen</td><td><a href="/schild3/unterricht-kataloge/klassenunterrichte-anlegen-tutorial.html">Klassenunterricht anlegen</a></td></tr><tr><td>Kurse und ihre Eigenschaften vorbereiten</td><td><a href="/schild3/unterricht-kataloge/kurse-schulbezogene-kataloge.html">Kurskatalog</a></td></tr><tr><td>Individuelle Kursarten festlegen</td><td><a href="/schild3/unterricht-kataloge/schuelerspezifische-kursarten-schulbezogene-kataloge.html">Schülerspezifische Kursarten</a></td></tr><tr><td>Kursunterricht außerhalb des Klassenverbands aufbauen</td><td><a href="/schild3/unterricht-kataloge/kursunterrichte-anlegen-tutorial.html">Kursunterricht anlegen</a></td></tr></tbody></table><p>Das Anlegen einer Stundentafel oder eines Kurses weist noch keine Leistungsdaten zu. Prüfen Sie vor der Zuweisung den Lernabschnitt sowie Fach, Jahrgang und Kursart. Die Fortschreibungsart eines Kurses bestimmt die Übernahme in den Zielabschnitt.</p><p>Für die Zuweisung nutzen Sie <a href="/schild3/faecher-kurse.html">Fächer und Kurse einer Schülergruppe zuweisen</a>. Die Stammdaten der Lehrkräfte stehen im Bereich <a href="/schild3/lehrkraefte.html">Lehrkräfte</a>.</p><h2 id="besondere-unterrichtsformen" tabindex="-1">Besondere Unterrichtsformen <a class="header-anchor" href="#besondere-unterrichtsformen" aria-label="Permalink to &quot;Besondere Unterrichtsformen&quot;">​</a></h2><p><a href="/schild3/schueler/thema-von-projektkurs-und-facharbeit-erfassen-tutorial.html">Projektkurse, Facharbeiten und ihre Themen erfassen</a> verbindet Fach- und Kursanlage mit Themen und Noten. Für <a href="/zeugnisse/sprachen.html">herkunftssprachlichen Unterricht</a> und Sprachprüfungen beachten Sie die gesonderten Zeugnis- und Erfassungsregeln.</p>',10)])])}const f=r(s,[["render",h]]);export{g as __pageData,f as default};
